func mergeGenerationTime(gen *GenerationMetadata, found *bool, ts time.Time) {
	if ts.IsZero() {
		return
	}
	ts = ts.UTC()
	if !*found {
		gen.OldestCheckpointAt = ts
		gen.NewestCheckpointAt = ts
		*found = true
		return
	}
	if ts.Before(gen.OldestCheckpointAt) {
		gen.OldestCheckpointAt = ts
	}
	if ts.After(gen.NewestCheckpointAt) {
		gen.NewestCheckpointAt = ts
	}
}

